    function populateArms(preferred = "") { if (!els.arm) return; const level = clean(els.level?.value), arms = armsForLevel(level); if (!level) { els.arm.innerHTML = `<option value="">Select level first</option>`; els.arm.disabled = true; return; } els.arm.innerHTML = `<option value="">Select arm</option>${arms.map(arm => `<option value="${esc(arm)}">${esc(armLabel(arm))}</option>`).join("")}`; els.arm.disabled = false; if (preferred && arms.includes(preferred)) els.arm.value = preferred; }
    function updateModeCards() { const level = upper(els.level?.value), isJss = level.startsWith("JSS"), isSs = level.startsWith("SS"); els.jssMode?.classList.toggle("active", isJss || !level); els.ssMode?.classList.toggle("active", isSs); }

