    const traitEls = { punctuality: els.traitPunctuality, attendance: els.traitAttendance, reliability: els.traitReliability, neatness: els.traitNeatness, politeness: els.traitPoliteness, honesty: els.traitHonesty, relationship: els.traitRelationship, self_control: els.traitSelfControl, attentiveness: els.traitAttentiveness, perseverance: els.traitPerseverance };
    const psychomotorEls = { handwriting: els.psyHandwriting, games: els.psyGames, sport: els.psySport, drawing: els.psyDrawing, crafts: els.psyCrafts, musical_skills: els.psyMusic };

    function openRemarksForAdmission(admission) { const key = normalizeAdmission(admission), index = state.filteredReports.findIndex(report => normalizeAdmission(reportAdmission(report)) === key); if (index < 0) { notify("Generate or preview this student's report before editing official remarks.", "warning", "Report Required"); return; } state.selectedIndex = index; renderReportList(); renderSelectedReport(); openRemarksEditor("student"); }
    function openRemarksEditor(scope = "student") { const report = getCurrentReport(); if (!report && scope === "student") { notify("Generate or preview a report first.", "warning", "No Report Selected"); return; } populateRemarksStudents(); if (els.remarksScope) els.remarksScope.value = scope; if (report) fillRemarksEditor(report); else { if (els.remarksSummary) els.remarksSummary.innerHTML = `<strong>Class-wide details</strong><span>${esc(armLabel(currentContext().class_arm))}</span><small>Apply common remarks, ratings or next-term details in one action.</small>`; if (els.remarksTeacherName) els.remarksTeacherName.value = clean(els.formTeacher?.value); if (els.remarksNextTerm) els.remarksNextTerm.value = clean(els.nextTerm?.value); } openModal("remarksTraitsModal"); notify(scope === "student" && report ? `Editing official remarks and ratings for ${reportName(report)}.` : "Class-wide remarks and ratings editor opened.", "info", "Report Editor Opened", 2200); }
    function openBulkRemarksEditor() { if (!validateContext() || !state.students.length) { notify("Load a class before applying bulk remarks or ratings.", "warning", "Load Class First"); return; } openRemarksEditor("all"); }
    function populateRemarksStudents() { if (!els.remarksSelect) return; const rows = state.filteredReports.length ? state.filteredReports.map(report => ({ admission_number: reportAdmission(report), full_name: reportName(report) })) : state.students; els.remarksSelect.innerHTML = `<option value="">Select student</option>${rows.map(item => `<option value="${esc(item.admission_number)}">${esc(item.full_name)} — ${esc(item.admission_number)}</option>`).join("")}`; const report = getCurrentReport(); if (report) els.remarksSelect.value = reportAdmission(report); }
    function setRatingInputs(map, nodes) { Object.entries(nodes).forEach(([key, node]) => { if (node) node.value = map?.[key] ?? ""; }); }
    function readRatingInputs(nodes) { const output = {}; Object.entries(nodes).forEach(([key, node]) => { const raw = clean(node?.value); if (!raw) output[key] = ""; else output[key] = Math.max(1, Math.min(6, Math.round(numberValue(raw, 0)))); }); return output; }

    function fillRemarksEditor(report = getCurrentReport()) {
        if (!report) return; setText(els.remarksSummary, ""); if (els.remarksSummary) els.remarksSummary.innerHTML = `<strong>${esc(reportName(report))}</strong><span>${esc(reportAdmission(report))} • ${esc(armLabel(reportClass(report)))}</span><small>Average ${formatNumber(report.average)}% • Grade ${esc(report.grade)} • Position ${esc(report.position_text || "—")}</small>`;
        if (els.remarksTeacherName) els.remarksTeacherName.value = clean(report.form_teacher || els.formTeacher?.value); if (els.teacherRemark) els.teacherRemark.value = clean(report.teacher_remark || autoTeacherRemark(report.average)); if (els.principalRemark) els.principalRemark.value = clean(report.principal_remark || autoPrincipalRemark(report.average)); if (els.remarksNextTerm) els.remarksNextTerm.value = clean(report.next_term || els.nextTerm?.value); setRatingInputs(report.affective || {}, traitEls); setRatingInputs(report.psychomotor || {}, psychomotorEls);
    }

    function autoTeacherRemark(average) { const avg = optionalNumber(average); if (avg === null) return ""; if (avg >= 80) return "An excellent student with strong academic performance. Keep it up."; if (avg >= 70) return "A very good performance. Continue to work consistently."; if (avg >= 60) return "A good result with room for further improvement."; if (avg >= 45) return "A fair performance. More consistent effort is encouraged."; return "Greater effort and closer academic support are required."; }
    function autoPrincipalRemark(average) { const avg = optionalNumber(average); if (avg === null) return ""; if (avg >= 80) return "An excellent result. Well done."; if (avg >= 70) return "A very good result. Keep it up."; if (avg >= 60) return "A good result."; if (avg >= 45) return "An average performance. More effort is encouraged."; return "Performance requires significant improvement."; }

    async function saveRemarksTraits() {
        const scope = clean(els.remarksScope?.value || "student").toLowerCase(), report = getCurrentReport(), c = currentContext(), base = { ...c, form_teacher: clean(els.remarksTeacherName?.value), teacher_remark: clean(els.teacherRemark?.value), principal_remark: clean(els.principalRemark?.value), next_term: clean(els.remarksNextTerm?.value), affective: readRatingInputs(traitEls), psychomotor: readRatingInputs(psychomotorEls) };
        if (scope === "student") { if (!report) { notify("Select a generated report first.", "warning", "No Report Selected"); return; } const admission = reportAdmission(report), payload = { ...base, admission_number: admission }; setButtonLoading(els.applyRemarks, true, "Saving..."); try { const data = await api(API.details, { method: "POST", body: JSON.stringify(payload) }), details = data.details || payload; Object.assign(report, { form_teacher: details.form_teacher, teacher_remark: details.teacher_remark, principal_remark: details.principal_remark, next_term: details.next_term, affective: details.affective || {}, psychomotor: details.psychomotor || {} }); const originalIndex = state.reports.findIndex(item => normalizeAdmission(reportAdmission(item)) === normalizeAdmission(admission)); if (originalIndex >= 0) Object.assign(state.reports[originalIndex], report); renderReportList(); renderSelectedReport(); closeModal("remarksTraitsModal"); setSourceText("remarks", "Official remarks and ratings are saved on the server."); notify(`Remarks, traits and psychomotor ratings saved for ${reportName(report)}.`, "saved", "Report Details Saved"); } catch (error) { notify(error.message || "Could not save report details.", "error", "Report Details Save Failed"); } finally { setButtonLoading(els.applyRemarks, false); } return; }
        const selected = scope === "selected" ? [...state.selectedAdmissions].length ? [...state.selectedAdmissions] : [...state.generatedSelections] : [], payload = { ...c, scope, admission_numbers: selected, auto_teacher_remark: !!els.remarksAutoTeacherAll?.checked, auto_principal_remark: !!els.remarksAutoPrincipalAll?.checked }; if (base.form_teacher) payload.form_teacher = base.form_teacher; if (base.teacher_remark) payload.teacher_remark = base.teacher_remark; if (base.principal_remark) payload.principal_remark = base.principal_remark; if (base.next_term) payload.next_term = base.next_term; if (els.remarksApplyAffective?.checked) payload.affective = base.affective; if (els.remarksApplyPsychomotor?.checked) payload.psychomotor = base.psychomotor; if (scope === "selected" && !selected.length) { notify("Select one or more students before applying class details to Selected Students.", "warning", "No Students Selected"); return; } setButtonLoading(els.applyRemarks, true, "Applying...");
        try { const data = await api(API.bulkDetails, { method: "POST", body: JSON.stringify(payload) }), wanted = scope === "all" ? null : new Set(selected.map(normalizeAdmission)); state.reports.forEach(item => { const admission = normalizeAdmission(reportAdmission(item)); if (wanted && !wanted.has(admission)) return; item.form_teacher = base.form_teacher || item.form_teacher; item.next_term = base.next_term || item.next_term; item.teacher_remark = payload.auto_teacher_remark ? autoTeacherRemark(item.average) : base.teacher_remark || item.teacher_remark; item.principal_remark = payload.auto_principal_remark ? autoPrincipalRemark(item.average) : base.principal_remark || item.principal_remark; if (payload.affective) item.affective = base.affective; if (payload.psychomotor) item.psychomotor = base.psychomotor; }); renderReportList(); renderSelectedReport(); closeModal("remarksTraitsModal"); notify(data.message || "Class-wide report details saved.", "saved", "Bulk Details Applied"); } catch (error) { notify(error.message || "Could not apply class-wide details.", "error", "Bulk Apply Failed"); } finally { setButtonLoading(els.applyRemarks, false); }
    }

    function resetTraitInputs() { setRatingInputs({}, traitEls); setRatingInputs({}, psychomotorEls); notify("Trait and psychomotor fields were cleared. They will remain blank until saved.", "info", "Ratings Cleared", 2600); }

    // ============================================================
    // MANUAL RESULT STUDIO / HYBRID FALLBACK
