    function manualDraftKey(admission = state.manualAdmission) { const c = currentContext(); return `emis_manual_${c.session}_${canonicalTerm(c.term)}_${c.class_arm}_${normalizeAdmission(admission)}`; }
    function manualStudentIndex() { return state.students.findIndex(student => normalizeAdmission(student.admission_number) === normalizeAdmission(state.manualAdmission)); }
    function manualScoreOrder() { return upper(currentContext().class_level).startsWith("JSS") ? ["ca1", "ca2", "test1", "test2", "exam"] : ["ass1", "ass2", "test", "exam"]; }
    function manualFieldLabel(field, max) { const labels = { ca1: "CA1", ca2: "CA2", test1: "TEST1", test2: "TEST2", ass1: "1ST ASS.", ass2: "2ND ASS.", test: "TEST", exam: "EXAM" }; return `${labels[field] || field.toUpperCase()} /${max}`; }
    function manualAttendanceNodes(prefix = "manual") { return prefix === "bulk" ? { days_open: els.bulkDaysOpen, present: els.bulkPresent, absent: els.bulkAbsent, late: els.bulkLate, sick: els.bulkSick, excused: els.bulkExcused } : { days_open: els.manualDaysOpen, present: els.manualPresent, absent: els.manualAbsent, late: els.manualLate, sick: els.manualSick, excused: els.manualExcused }; }
    function readAttendanceNodes(prefix = "manual") { const out = {}; Object.entries(manualAttendanceNodes(prefix)).forEach(([key, node]) => out[key] = Math.max(0, Math.round(numberValue(node?.value, 0)))); return out; }
    function writeAttendanceNodes(values = {}, prefix = "manual") { Object.entries(manualAttendanceNodes(prefix)).forEach(([key, node]) => { if (node) node.value = values?.[key] ?? 0; }); updateManualAttendancePreview(prefix); }
    function updateManualAttendancePreview(prefix = "manual") { const a = readAttendanceNodes(prefix), credit = a.present + a.late + a.excused, pct = a.days_open ? Math.round((credit / a.days_open) * 1000) / 10 : 0; setText(prefix === "bulk" ? els.bulkAttendancePercent : els.manualAttendancePercent, `${pct}%`); return { ...a, attendance_percentage: pct }; }
    function markManualDirty() { state.manualDirty = true; if (els.manualUnsaved) { els.manualUnsaved.textContent = "Unsaved changes"; els.manualUnsaved.classList.add("dirty"); } persistManualBrowserDraft(); }
    function markManualSaved(label = "Saved") { state.manualDirty = false; if (els.manualUnsaved) { els.manualUnsaved.textContent = label; els.manualUnsaved.classList.remove("dirty"); } }
    function findManualEntry(subject) { const entries = state.manualRecord?.subjects && typeof state.manualRecord.subjects === "object" ? Object.values(state.manualRecord.subjects) : []; return entries.find(item => upper(item?.subject) === upper(subject)) || null; }

    function renderManualScoreGrid() {
        if (!els.manualHead || !els.manualBody) return; const fields = manualScoreOrder(), isJss = upper(currentContext().class_level).startsWith("JSS"); if (els.manualModeTitle) els.manualModeTitle.textContent = isJss ? "JSS Manual Entry — CA /60 + Exam /40" : "SS Manual Entry — CA /30 + Exam /70";
        els.manualHead.innerHTML = `<tr><th class="manual-include-col">Use</th><th class="manual-subject-col">Subject</th>${fields.map(field => `<th>${esc(manualFieldLabel(field, state.manualScoreFields[field] || 0))}</th>`).join("")}<th>Total</th><th>Grade</th></tr>`;
        if (!state.manualSubjects.length) { els.manualBody.innerHTML = `<tr><td colspan="${fields.length + 4}" class="report-table-empty">No subjects are configured for this class.</td></tr>`; return; }
        els.manualBody.innerHTML = state.manualSubjects.map(subject => { const entry = findManualEntry(subject) || {}, included = !!entry.included || fields.some(field => entry[field] !== null && entry[field] !== undefined && entry[field] !== ""); return `<tr data-manual-row="${esc(subject)}" class="${included ? "included" : ""}"><td><input type="checkbox" data-manual-include="${esc(subject)}" ${included ? "checked" : ""}></td><td class="manual-subject-name">${esc(subject)}</td>${fields.map(field => `<td><input class="manual-score-input" data-manual-subject="${esc(subject)}" data-manual-score="${field}" type="number" min="0" max="${state.manualScoreFields[field] || 100}" step="0.01" value="${entry[field] ?? ""}"></td>`).join("")}<td class="manual-live-total" data-manual-total="${esc(subject)}">—</td><td class="manual-live-grade" data-manual-grade="${esc(subject)}">—</td></tr>`; }).join("");
        $$('[data-manual-include]', els.manualBody).forEach(box => box.addEventListener("change", () => { box.closest("tr")?.classList.toggle("included", box.checked); markManualDirty(); refreshManualCalculations(); })); $$('[data-manual-score]', els.manualBody).forEach(input => input.addEventListener("input", () => { if (clean(input.value)) { const box = input.closest("tr")?.querySelector('[data-manual-include]'); if (box) box.checked = true; input.closest("tr")?.classList.add("included"); } markManualDirty(); refreshManualCalculations(); })); refreshManualCalculations();
    }

    function collectManualSubjects(validate = true) { const fields = manualScoreOrder(), rows = []; let invalid = 0; $$('[data-manual-row]', els.manualBody).forEach(row => { const subject = row.dataset.manualRow, included = !!row.querySelector('[data-manual-include]')?.checked, item = { subject, included }; fields.forEach(field => { const input = row.querySelector(`[data-manual-score="${field}"]`), raw = clean(input?.value), max = numberValue(input?.max, 100), value = raw === "" ? null : Number(raw); if (raw !== "" && (!Number.isFinite(value) || value < 0 || value > max)) { invalid++; input?.classList.add("invalid"); } else input?.classList.remove("invalid"); item[field] = raw === "" ? null : value; }); if (included || fields.some(field => item[field] !== null)) rows.push(item); }); if (validate && invalid) throw new Error(`${invalid} manual score field(s) are outside their allowed mark range.`); return rows; }
    function refreshManualCalculations() { const fields = manualScoreOrder(); let includedCount = 0, completeCount = 0, invalid = 0; $$('[data-manual-row]', els.manualBody).forEach(row => { const included = !!row.querySelector('[data-manual-include]')?.checked; if (!included) { setText(row.querySelector('[data-manual-total]'), "—"); setText(row.querySelector('[data-manual-grade]'), "—"); return; } includedCount++; let total = 0, complete = true; fields.forEach(field => { const input = row.querySelector(`[data-manual-score="${field}"]`), raw = clean(input?.value), value = Number(raw), max = numberValue(input?.max, 100); if (!raw) complete = false; else if (!Number.isFinite(value) || value < 0 || value > max) { complete = false; invalid++; input.classList.add("invalid"); } else { total += value; input.classList.remove("invalid"); } }); if (complete) completeCount++; const grade = !complete ? "—" : total >= 80 ? "A" : total >= 70 ? "B" : total >= 60 ? "C" : total >= 45 ? "D" : total >= 40 ? "E" : "F"; setText(row.querySelector('[data-manual-total]'), complete ? formatNumber(total) : "—"); setText(row.querySelector('[data-manual-grade]'), grade); }); setText(els.manualEnteredCount, `${completeCount} complete / ${includedCount} selected`); setText(els.manualProgressLabel, `${includedCount} subject${includedCount === 1 ? "" : "s"} entered • ${completeCount} complete`); if (els.manualProgressBar) els.manualProgressBar.style.width = `${includedCount ? Math.round((completeCount / includedCount) * 100) : 0}%`; if (els.manualValidation) els.manualValidation.textContent = invalid ? `${invalid} score field(s) need correction before saving.` : "All entered scores are within the configured JSS/SS maximum marks."; els.manualValidation?.classList.toggle("error", !!invalid); }
    function manualPayload(status = "DRAFT") { return { ...currentContext(), admission_number: state.manualAdmission, subjects: collectManualSubjects(true), attendance: readAttendanceNodes("manual"), attendance_override_enabled: !!els.manualAttendanceOverride?.checked, prefer_manual_scores: !!els.manualPreferScores?.checked, teacher_note: clean(els.manualTeacherNote?.value), status }; }
    function persistManualBrowserDraft() { if (!state.manualAdmission) return; try { localStorage.setItem(manualDraftKey(), JSON.stringify({ subjects: collectManualSubjects(false), attendance: readAttendanceNodes("manual"), attendance_override_enabled: !!els.manualAttendanceOverride?.checked, prefer_manual_scores: !!els.manualPreferScores?.checked, teacher_note: clean(els.manualTeacherNote?.value) })); } catch (_) {} }
    function restoreManualBrowserDraft() { if (!state.manualAdmission || (state.manualRecord?.subjects && Object.keys(state.manualRecord.subjects).length)) return false; try { const raw = localStorage.getItem(manualDraftKey()); if (!raw) return false; const draft = JSON.parse(raw); state.manualRecord = { ...state.manualRecord, ...draft, subjects: Object.fromEntries((draft.subjects || []).map(item => [upper(item.subject), item])) }; return true; } catch (_) { return false; } }

    async function openManualResultStudio(preferredAdmission = "") { if (!validateContext() || !state.students.length) { notify("Load the class before opening Manual Result Studio.", "warning", "Load Class First"); return; } if (els.manualStudentSelect) els.manualStudentSelect.innerHTML = state.students.map(student => `<option value="${esc(student.admission_number)}">${esc(student.full_name)} — ${esc(student.admission_number)}</option>`).join(""); const preferred = normalizeAdmission(preferredAdmission) || [...state.selectedAdmissions][0] || normalizeAdmission(getCurrentReport() ? reportAdmission(getCurrentReport()) : "") || normalizeAdmission(state.students[0]?.admission_number); state.manualAdmission = preferred; if (els.manualStudentSelect) { const option = [...els.manualStudentSelect.options].find(item => normalizeAdmission(item.value) === preferred); if (option) els.manualStudentSelect.value = option.value; } openModal("manualResultStudioModal"); await loadManualStudent(preferred); notify("Manual Result Studio is ready. Scores are kept separate from automated CA/CBT data until Manual or Hybrid generation is used.", "info", "Manual Studio Opened", 3200); }
    async function loadManualStudent(admission) { const key = normalizeAdmission(admission); if (!key) return; state.manualAdmission = key; if (els.manualDraftStatus) els.manualDraftStatus.textContent = "Loading manual record..."; try { const data = await api(`${API.manual}?${query({ ...currentContext(), admission_number: key })}`); state.manualSubjects = Array.isArray(data.subjects) ? data.subjects : []; state.manualScoreFields = data.score_fields || {}; state.manualRecord = data.record && typeof data.record === "object" ? data.record : {}; const restored = restoreManualBrowserDraft(), student = state.students.find(item => normalizeAdmission(item.admission_number) === key); if (els.manualStudentSelect && student) els.manualStudentSelect.value = student.admission_number; if (els.manualMeta) els.manualMeta.innerHTML = `<strong>${esc(student?.full_name || key)}</strong><span>${esc(student?.admission_number || key)} • ${esc(armLabel(student?.class_arm || currentContext().class_arm))}</span>`; if (els.manualPreferScores) els.manualPreferScores.checked = !!state.manualRecord.prefer_manual_scores; if (els.manualAttendanceOverride) els.manualAttendanceOverride.checked = !!state.manualRecord.attendance_override_enabled; writeAttendanceNodes(state.manualRecord.attendance || {}, "manual"); if (els.manualTeacherNote) els.manualTeacherNote.value = clean(state.manualRecord.teacher_note); renderManualScoreGrid(); markManualSaved(restored ? "Browser draft restored" : state.manualRecord.updated_at ? `Saved ${state.manualRecord.updated_at}` : "New draft"); if (els.manualDraftStatus) els.manualDraftStatus.textContent = state.manualRecord.status ? `${state.manualRecord.status} • ${state.manualRecord.updated_by || "Staff"}` : "New manual draft"; } catch (error) { notify(error.message || "Could not load manual result data.", "error", "Manual Load Failed"); } }
    async function navigateManualStudent(direction) { const index = manualStudentIndex(); if (index < 0) return; if (state.manualDirty && !window.confirm("This student has unsaved manual changes. Continue without saving?")) return; const next = Math.max(0, Math.min(state.students.length - 1, index + direction)); await loadManualStudent(state.students[next].admission_number); }
    async function saveManualRecordFromStudio(status = "DRAFT", silent = false) { if (!state.manualAdmission) return null; let payload; try { payload = manualPayload(status); } catch (error) { notify(error.message, "error", "Manual Validation Failed"); return null; } setButtonLoading(els.saveManualDraft, true, "Saving..."); try { const data = await api(API.manual, { method: "POST", body: JSON.stringify(payload) }); state.manualRecord = data.record || payload; try { localStorage.removeItem(manualDraftKey()); } catch (_) {} markManualSaved(status === "FINAL" ? "Final saved" : "Draft saved"); if (els.manualDraftStatus) els.manualDraftStatus.textContent = `${status} • saved now`; if (!silent) notify(data.message || "Manual report record saved.", "saved", status === "FINAL" ? "Manual Result Saved" : "Manual Draft Saved"); return data; } catch (error) { notify(error.message || "Could not save manual report data.", "error", "Manual Save Failed"); return null; } finally { setButtonLoading(els.saveManualDraft, false); } }
    async function deleteManualStudentRecord() { if (!state.manualAdmission) return; const student = state.students.find(item => normalizeAdmission(item.admission_number) === normalizeAdmission(state.manualAdmission)); if (!window.confirm(`Clear all saved manual scores and attendance for ${student?.full_name || state.manualAdmission}? Automated CA/CBT records will NOT be deleted.`)) return; try { await api(API.manual, { method: "DELETE", body: JSON.stringify({ ...currentContext(), admission_number: state.manualAdmission }) }); try { localStorage.removeItem(manualDraftKey()); } catch (_) {} state.manualRecord = {}; renderManualScoreGrid(); writeAttendanceNodes({}, "manual"); if (els.manualTeacherNote) els.manualTeacherNote.value = ""; markManualSaved("Manual data cleared"); notify("Manual student data cleared. Automated records were left untouched.", "success", "Manual Data Cleared"); } catch (error) { notify(error.message || "Could not clear manual data.", "error", "Clear Failed"); } }

    async function generateManualOrHybrid(mode = "manual", scope = "selected", forcedAdmissions = null) { if (!validateContext() || state.loading) return; let admissions = forcedAdmissions || (scope === "selected" ? [...state.selectedAdmissions] : []); if (scope === "selected" && !admissions.length) { const current = getCurrentReport(); if (current) admissions = [reportAdmission(current)]; } if (scope === "selected" && !admissions.length) { notify("Select at least one student first.", "warning", "No Students Selected"); return; } const label = mode === "hybrid" ? "Hybrid" : "Manual", button = mode === "hybrid" ? (scope === "selected" ? els.generateHybridSelected : els.generateHybridClass) : (scope === "selected" ? els.generateManualSelected : els.generateManualClass); state.loading = true; setButtonLoading(button, true, "Generating..."); setStatus(`${label} Generation`, `Preparing ${scope === "selected" ? admissions.length : "class"} report(s)...`, "waiting"); try { const data = await api(API.manualGenerate, { method: "POST", body: JSON.stringify({ ...currentContext(), mode, admission_numbers: admissions, save_snapshot: true }) }), incoming = Array.isArray(data.reports) ? data.reports : []; attachSnapshotIds(incoming, data.saved_snapshots); const merge = mergeGeneratedReports(incoming, { selectIncoming: true, openIncoming: "last" }); renderReportList(); renderSelectedReport(); updateStats({ ...(data.summary || {}), students_in_class: state.students.length, generated: state.reports.length, subjects: countSubjects(state.reports) }); setStatus(`${label} Reports Ready`, `${incoming.length} report(s) generated • ${merge.total} now in the list.`, "ready"); setPreviewStatus("Ready", "ready"); notify(`${incoming.length} ${label.toLowerCase()} report(s) generated successfully.`, "generated", `${label} Generation Complete`); } catch (error) { notify(error.message || `${label} report generation failed.`, "error", `${label} Generation Failed`); setStatus(`${label} Generation Failed`, error.message, "error"); } finally { state.loading = false; setButtonLoading(button, false); } }
    async function saveAndGenerateManual(mode = "manual") { const saved = await saveManualRecordFromStudio("FINAL", true); if (!saved) return; await generateManualOrHybrid(mode, "selected", [state.manualAdmission]); closeModal("manualResultStudioModal"); }

