    function updateBulkAttendanceTarget() { const scope = clean(els.bulkAttendanceScope?.value || "selected"), count = scope === "all" ? state.students.length : state.selectedAdmissions.size; setText(els.bulkAttendanceTarget, scope === "all" ? `${count} students in ${armLabel(currentContext().class_arm)}` : `${count} selected student${count === 1 ? "" : "s"}`); updateManualAttendancePreview("bulk"); }
    async function applyBulkAttendance() { const scope = clean(els.bulkAttendanceScope?.value || "selected"), admissions = scope === "selected" ? [...state.selectedAdmissions] : []; if (scope === "selected" && !admissions.length) { notify("Select one or more students first.", "warning", "No Students Selected"); return; } const payload = { ...currentContext(), scope, admission_numbers: admissions, attendance: readAttendanceNodes("bulk"), attendance_override_enabled: !!els.bulkAttendanceOverride?.checked }; setButtonLoading(els.applyBulkAttendance, true, "Applying..."); try { const data = await api(API.bulkDetails, { method: "POST", body: JSON.stringify(payload) }), wanted = scope === "all" ? null : new Set(admissions.map(normalizeAdmission)), attendance = data.attendance || payload.attendance; state.reports.forEach(report => { const key = normalizeAdmission(reportAdmission(report)); if (wanted && !wanted.has(key)) return; report.attendance = attendance; report.has_attendance = true; report.manual_attendance_used = true; }); renderReportList(); renderSelectedReport(); closeModal("bulkAttendanceModal"); notify(data.message || "Attendance applied successfully.", "saved", "Bulk Attendance Applied"); } catch (error) { notify(error.message || "Could not apply bulk attendance.", "error", "Bulk Attendance Failed"); } finally { setButtonLoading(els.applyBulkAttendance, false); } }

